## code
```go
package gtree_test

import (
	"fmt"
	"strings"
	"testing"

	"github.com/ddddddO/gtree"
	"github.com/xlab/treeprint"
)

func BenchmarkGtree(b *testing.B) {
	for b.Loop() {
		root := gtree.NewRoot(".")
		buildGtree(root, 5, 5) // A tree with depth of 5 and width of 5.

		ret := &strings.Builder{}
		gtree.OutputFromRoot(ret, root)
		_ = ret.String()
	}
}

func buildGtree(parent *gtree.Node, depth, width int) {
	if depth <= 0 {
		return
	}
	for i := range width {
		child := parent.Add(fmt.Sprintf("n-%d-%d", depth, i))
		buildGtree(child, depth-1, width)
	}
}

func BenchmarkTreeprint(b *testing.B) {
	for b.Loop() {
		tree := treeprint.New()
		buildTreeprint(tree, 5, 5) // A tree with depth of 5 and width of 5.

		_ = tree.String()
	}
}

func buildTreeprint(parent treeprint.Tree, depth, width int) {
	if depth <= 0 {
		return
	}
	for i := range width {
		if depth == 1 {
			parent.AddNode(fmt.Sprintf("n-%d-%d", depth, i))
		} else {
			child := parent.AddBranch(fmt.Sprintf("n-%d-%d", depth, i))
			buildTreeprint(child, depth-1, width)
		}
	}
}
```

When removing `border-right` from `.cart-drawer`, the entire source line was deleted — `border-right` and `transform: translateX(100%)` were co-located on the same line. This left the drawer permanently at `translateX(0)` (visible), making `openCart()`/`closeCart()`'s class toggle a no-op.

## Change

Adds back the single missing declaration to the base `.cart-drawer` rule:

```css
.cart-drawer {
  /* ... */
  background: rgb(110, 67, 77); border-bottom: 2px solid rgba(217, 158, 84, 0.85);
  transform: translateX(100%);   /* ← restored */
  transition: transform 250ms ease; /* animates slide-in/out */
  /* ... */
}
.cart-drawer.open { transform: translateX(0); } /* already present, untouched */
```

`border-right` and `.cart-drawer-header`'s `border-bottom` remain removed. No other lines touched.
